const ENGINE6_ACTIVE_ROUTE_PRODUCT_CODE_ENTRIES =
  ENGINE6_ROUTE_PRODUCT_CODE_ENTRIES.filter(
    ([, productCode]) => !isExcludedProductCode(productCode)
  );

export const ENGINE6_CONFIGURED_PRODUCT_CODES = Array.from(
  new Set(
    ENGINE6_ACTIVE_ROUTE_PRODUCT_CODE_ENTRIES.map(
      ([, productCode]) => productCode
    )
  )
);

export const ENGINE6_ORIGINAL_MERCHANT_APPROVED_PRODUCT_CODES = new Set(
  ENGINE6_CONFIGURED_PRODUCT_CODES.slice(0, 55)
);

const ENGINE6_ROUTE_PRODUCT_CODE_BY_PATH: Record<string, string> =
  Object.fromEntries(ENGINE6_ACTIVE_ROUTE_PRODUCT_CODE_ENTRIES);

const ENGINE6_PATH_BY_PRODUCT_CODE: Record<string, string> = Object.fromEntries(
  ENGINE6_ACTIVE_ROUTE_PRODUCT_CODE_ENTRIES.map(([path, productCode]) => [
    productCode,
    path,
  ])
);

export const ENGINE6_EXPLICIT_ROUTE_REPLACEMENTS = new Set<string>(
  ENGINE6_OVERLAP_REPLACEMENT_CONFIGS.map(config => config.canonicalPath)
);

export const resolveEngine6ProductCodeForPath = (path: string) =>
  ENGINE6_ROUTE_PRODUCT_CODE_BY_PATH[path] ?? null;

export const resolveEngine6PathForProductCode = (productCode: string) =>
  ENGINE6_PATH_BY_PRODUCT_CODE[productCode] ?? null;

export const resolveEngine6OverlapReplacement = (productCode: string) =>
  ENGINE6_OVERLAP_REPLACEMENT_BY_PRODUCT_CODE[productCode] ?? null;

export const isEngine6CanonicalPath = (path: string) =>
  Boolean(resolveEngine6ProductCodeForPath(path));

export const engine6OverlapReplacementConfigs =
  ENGINE6_OVERLAP_REPLACEMENT_CONFIGS;
